/**
 * Returns a fast lookup Set of icon names for a package.
 */
const ICON_SETS: Record<string, Set<string>> = {};
for (const [pkgId, pkg] of Object.entries(ICON_PACKAGES)) {
  ICON_SETS[pkgId] = new Set(pkg.icons);
}

/**
 * Checks if a word is a valid icon name in the specified package.
 */
export function isIconName(packageKey: IconPackageKey, word: string): boolean {
  if (packageKey === 'off') return false;
  return ICON_SETS[packageKey]?.has(word) ?? false;
}

/**
 * Helper to compute proper Phosphor Icon CSS class names based on weight suffix.
 */
export function getPhosphorIconClasses(iconName: string): string {
  if (iconName.endsWith('-bold')) {
    return `ph-bold ph-${iconName.slice(0, -5)}`;
  }
  if (iconName.endsWith('-duotone')) {
    return `ph-duotone ph-${iconName.slice(0, -8)}`;
  }
  if (iconName.endsWith('-fill')) {
    return `ph-fill ph-${iconName.slice(0, -5)}`;
  }
  if (iconName.endsWith('-light')) {
    return `ph-light ph-${iconName.slice(0, -6)}`;
  }
  if (iconName.endsWith('-thin')) {
    return `ph-thin ph-${iconName.slice(0, -5)}`;
  }
  return `ph ph-${iconName}`;
}

/**
 * Helper to render an icon element for DOM injection.
 */
export function createIconElement(packageKey: IconPackageKey, iconName: string): HTMLElement {
  const el = document.createElement(packageKey === 'material' ? 'span' : 'i');
  
  switch (packageKey) {
    case 'bootstrap':
      el.className = `bi bi-${iconName}`;
      break;
    case 'lucide':
      el.className = `icon-${iconName}`;
      break;
    case 'iconoir':
      el.className = `iconoir-${iconName}`;
      break;
    case 'tabler':
      el.className = `ti ti-${iconName}`;
      break;
    case 'material':
      el.className = 'material-symbols-outlined';
      el.textContent = iconName.replace(/-/g, '_');
      break;
    case 'boxicons':
      el.className = iconName.startsWith('bx') ? `bx ${iconName}` : `bx bx-${iconName}`;
      break;
    case 'phosphor':
      el.className = getPhosphorIconClasses(iconName);
      break;
  }
  
  el.style.fontSize = '14px';
  el.style.lineHeight = '1';
  el.style.display = 'inline-block';
  el.style.verticalAlign = 'middle';

  return el;
}
